"""Source-row anchoring, canonical financial context, Decimal arithmetic and rules."""

from datetime import date
from decimal import Decimal, InvalidOperation, localcontext
from typing import Literal
import re
from pydantic import BaseModel, ConfigDict, Field, field_validator

LABELS = {
    "revenue": ("total net sales", "net sales", "revenue", "营业收入", "营业总收入"),
    "net_profit": ("net income", "net profit", "净利润"),
    "operating_cash_flow": (
        "cash generated by operating activities",
        "cash provided by operating activities",
        "cash used in operating activities",
        "operating cash flow",
        "经营活动产生的现金流量净额",
    ),
    "accounts_receivable": ("accounts receivable", "trade receivables", "应收账款"),
    "current_assets": ("total current assets", "current assets", "流动资产合计"),
    "current_liabilities": (
        "total current liabilities",
        "current liabilities",
        "流动负债合计",
    ),
    "total_assets": ("total assets", "资产总计", "资产总额"),
    "total_liabilities": ("total liabilities", "负债合计", "负债总额"),
}
FIELDS = tuple(LABELS)
CURRENCIES = {
    "USD",
    "CNY",
    "HKD",
    "EUR",
    "GBP",
    "JPY",
    "AUD",
    "CAD",
    "CHF",
    "SGD",
    "NZD",
    "KRW",
    "INR",
    "TWD",
}
# Exclude XLSX coordinate digits (B12=...) and embedded identifier digits.
NUMBER = re.compile(r"(?<![\w.])\(?-?\d[\d,]*(?:\.\d+)?\)?(?![\w.])")


class Figure(BaseModel):
    model_config = ConfigDict(extra="forbid")
    field: str
    value: str = Field(max_length=60)
    period: str = Field(max_length=21)
    currency: str = Field(max_length=20)
    scope: Literal["consolidated", "parent"]
    scale: int = Field(default=1, strict=True)
    source_id: str = Field(min_length=1, max_length=300)
    line_number: int = Field(ge=1, le=100000, strict=True)
    number_index: int = Field(ge=0, le=100, strict=True)
    quote: str = Field(min_length=1, max_length=1500)

    @field_validator("field")
    @classmethod
    def known_field(cls, value):
        if value not in FIELDS:
            raise ValueError("Unknown field")
        return value

    @field_validator("period")
    @classmethod
    def canonical_period(cls, value):
        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}/\d{4}-\d{2}-\d{2}", value):
            raise ValueError(
                "Period must be YYYY-MM-DD/YYYY-MM-DD (reporting interval)"
            )
        start, end = (date.fromisoformat(v) for v in value.split("/"))
        if not 0 < (end - start).days <= 550:
            raise ValueError("Invalid reporting interval")
        return value

    @field_validator("currency")
    @classmethod
    def canonical_currency(cls, value):
        value = value.strip().upper()
        if value not in CURRENCIES:
            raise ValueError("Unsupported ISO currency")
        return value

    @field_validator("value")
    @classmethod
    def number(cls, value):
        try:
            number = Decimal(value)
        except InvalidOperation:
            raise ValueError("Invalid decimal")
        if not number.is_finite() or abs(number) > Decimal("1e20"):
            raise ValueError("Number out of bounds")
        if number.as_tuple().exponent < -12:
            raise ValueError("Maximum 12 decimal places")
        return str(number)

    @field_validator("scale")
    @classmethod
    def unit(cls, value):
        if value not in (1, 1000, 10000, 1000000, 100000000, 1000000000):
            raise ValueError("Unsupported scale")
        return value


def label_matches(field, line):
    # Match a row label before its first numeric value, rather than any label on a page.
    first = next(NUMBER.finditer(line), None)
    label = line[: first.start()] if first else line
    label = re.sub(r"\b[A-Z]+\d+=", "", label)  # XLSX coordinate prefix
    normalized = re.sub(r"[\W_]+", "", label.casefold())
    for candidate in LABELS[field]:
        expected = re.sub(r"[\W_]+", "", candidate.casefold())
        if normalized == expected or (
            field == "accounts_receivable" and normalized == expected + "net"
        ):
            return True
    return False


def verify(figures, sources):
    """Check exact line, selected numeric token and supported label; not semantic entailment."""
    source_by_id = {s["id"]: s for s in sources}
    valid, rejected = [], []
    for raw in figures:
        try:
            f = Figure.model_validate(raw)
            line = (
                source_by_id[f.source_id]["text"]
                .splitlines()[f.line_number - 1]
                .strip()
            )
            if f.quote != line:
                raise ValueError("Quote must equal the anchored source line")
            if not label_matches(f.field, line):
                raise ValueError("Field does not match supported row label")
            tokens = list(NUMBER.finditer(line))
            n = tokens[f.number_index].group()
            number = Decimal(n.replace(",", "").replace("(", "-").replace(")", ""))
            if Decimal(f.value) != number:
                raise ValueError("Value does not match selected numeric token")
            valid.append(f.model_dump())
        except (ValueError, KeyError, IndexError, TypeError):
            rejected.append(
                "Extraction rejected: schema, row label, line anchor or selected numeric token mismatch"
            )
    return valid, rejected


def validated_context(figures):
    """Applied at confirmation AND every calculation/tool entry, including direct callers."""
    parsed = [Figure.model_validate(f).model_dump() for f in figures]
    if not parsed or len(parsed) > len(FIELDS):
        raise ValueError("One to eight figures required")
    if len({f["field"] for f in parsed}) != len(parsed):
        raise ValueError("Duplicate/ambiguous fields")
    if any(f["scope"] != "consolidated" for f in parsed):
        raise ValueError("Consolidated scope required")
    if len({(f["period"], f["currency"], f["scope"]) for f in parsed}) != 1:
        raise ValueError("Reporting period/currency/scope mismatch")
    return parsed


RATIOS = {
    "current_ratio": ("current_assets", "current_liabilities"),
    "debt_to_assets": ("total_liabilities", "total_assets"),
    "cash_to_profit": ("operating_cash_flow", "net_profit"),
    "receivables_to_revenue": ("accounts_receivable", "revenue"),
}


def calculate(figures):
    figures = validated_context(figures)
    by = {f["field"]: f for f in figures}
    ratios, missing = {}, []
    for name, (a, b) in RATIOS.items():
        if a not in by or b not in by:
            missing.append(f"{name}: missing inputs")
            continue
        x, y = by[a], by[b]
        with localcontext() as context:
            context.prec = 80
            denominator = Decimal(y["value"]) * y["scale"]
            if denominator <= 0:
                missing.append(f"{name}: denominator must be positive")
                continue
            value = Decimal(x["value"]) * x["scale"] / denominator
            rounded = str(value.quantize(Decimal(".0001")))
        ratios[name] = {
            "value": rounded,
            "unrounded": str(value),
            "formula": f"{a} / {b}",
            "inputs": [a, b],
            "source_ids": list(dict.fromkeys([x["source_id"], y["source_id"]])),
        }
    return ratios, missing


def screen(figures, ratios):
    figures = validated_context(figures)
    signals = []
    for name, op, threshold, code in (
        ("current_ratio", "lt", "1", "LIQUIDITY"),
        ("debt_to_assets", "gt", ".70", "LEVERAGE"),
        ("receivables_to_revenue", "gt", ".35", "RECEIVABLES"),
    ):
        if name in ratios:
            v = Decimal(ratios[name]["unrounded"])
            if (op == "lt" and v < Decimal(threshold)) or (
                op == "gt" and v > Decimal(threshold)
            ):
                signals.append(
                    {
                        "code": code,
                        "severity": "medium",
                        "metric": name,
                        "threshold": threshold,
                        "operator": op,
                        **ratios[name],
                    }
                )
    by = {f["field"]: f for f in figures}
    if all(k in by for k in ("net_profit", "operating_cash_flow")):
        p, c = by["net_profit"], by["operating_cash_flow"]
        if Decimal(c["value"]) < 0 < Decimal(p["value"]):
            signals.append(
                {
                    "code": "CASH_PROFIT_DIVERGENCE",
                    "severity": "high",
                    "source_ids": [p["source_id"], c["source_id"]],
                }
            )
    return signals


def check_balance(figures):
    figures = validated_context(figures)
    by = {f["field"]: f for f in figures}
    a, l = by.get("total_assets"), by.get("total_liabilities")
    if not a or not l:
        return {"status": "unavailable", "reason": "missing balance inputs"}
    with localcontext() as context:
        context.prec = 80
        return {
            "liabilities_exceed_assets": Decimal(l["value"]) * l["scale"]
            > Decimal(a["value"]) * a["scale"],
            "source_ids": [a["source_id"], l["source_id"]],
        }
